using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.GoLive;
namespace OrcaFacil.Web.Pages.Admin; [Authorize(Roles="SuperAdministrator,SuperAdmin,PlatformSupport")] public sealed class ProductionReadinessModel(IConfiguration configuration, ProductionReadinessService service, IWebHostEnvironment environment):PageModel { public IReadOnlyList<ProductionCheck> Checks {get;private set;}=[]; public bool Ready=>service.IsReady(Checks); public void OnGet(){var cs=configuration.GetConnectionString("DefaultConnection"); bool connectionOk=true; try{service.ValidateConnectionString(cs);}catch{connectionOk=false;} Checks=[new("connection","ConnectionString operacional",connectionOk,true,"Configure o banco de produção."),new("https","HTTPS e cookie seguro",configuration.GetValue<bool>("HttpsRedirection:Enabled")||environment.IsDevelopment(),true,"Ative HTTPS na publicação."),new("dataprotection","DataProtection persistente",!string.IsNullOrWhiteSpace(configuration["DataProtection:KeysPath"])||environment.IsDevelopment(),true,"Defina o diretório persistente das chaves."),new("smtp","SMTP configurado ou desabilitado",!string.IsNullOrWhiteSpace(configuration["Email:Enabled"]),false,"Declare explicitamente a política de e-mail."),new("exceptions","Erros sanitizados",!environment.IsDevelopment(),true,"Não publique com DeveloperExceptionPage.")];} }
